import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Aksharabhyasa (First-letter writing) source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/21-vidyarambha-profile.md","filePath":"reference/21-vidyarambha-profile.md","lastUpdated":1788614098000}'),n={name:"reference/21-vidyarambha-profile.md"};function o(d,e,s,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="aksharabhyasa-first-letter-writing-source-profile" tabindex="-1">Aksharabhyasa (First-letter writing) source profile <a class="header-anchor" href="#aksharabhyasa-first-letter-writing-source-profile" aria-label="Permalink to &quot;Aksharabhyasa (First-letter writing) source profile&quot;">​</a></h1><h2 id="product-identity-and-exact-scope" tabindex="-1">Product identity and exact scope <a class="header-anchor" href="#product-identity-and-exact-scope" aria-label="Permalink to &quot;Product identity and exact scope&quot;">​</a></h2><p>This profile assesses the first-letter-writing rite described under B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter VIII, “Post-natal ceremonies” / “Commencing education (Aksharabhyasa),” internal printed page 23 (physical PDF page 26) in the inspected 2020 Chistabo derivative:</p><p><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">inspected 2020 Chistabo derivative</a></p><p>The bibliographic work and inspected artifact are deliberately separate:</p><ul><li><code>BVR-MUHURTHA-1993</code> is the catalogued 181-page UBS 1993 work. No scan of that edition was inspected.</li><li><code>BVR-MUHURTHA-CHISTABO-2020</code> is the directly inspected 78-physical-page 2020 Chistabo re-edited transcription. Its editorial notice, checksum, byte size, and page-number model are registered in <a href="provenance.json">the provenance ledger</a>.</li></ul><p>The controlling passage is B. V. Raman, Chapter VIII, “Post-natal ceremonies” / “Commencing education (Aksharabhyasa),” at <strong>internal printed p. 23 (physical PDF p. 26)</strong> in the inspected derivative. The catalogued work is linked as the related bibliographic identity; exact edition equivalence has not been established.</p><p>Raman is a modern synthesis, not primary scripture. This product helps audit one disclosed election method. It neither limits when a child may learn nor replaces educational, developmental, family, or officiant judgment.</p><h2 id="inputs-and-chart-facts" tabindex="-1">Inputs and chart facts <a class="header-anchor" href="#inputs-and-chart-facts" aria-label="Permalink to &quot;Inputs and chart facts&quot;">​</a></h2><p>The browser first applies the documented Panchangam, safeguard, and personal gates. Surviving Drik candidates are sampled at the offered window edges and on both sides of each known interior Drik Lagna transition. The sidecar supplies nine-graha Rashis; the browser recomputes Whole Sign houses in the validated local Drik/Lahiri Lagna frame.</p><p>Let:</p><ul><li><code>H(p)</code> be the recomputed Whole Sign house of graha <code>p</code>.</li><li><code>G</code> contain Surya, Chandra, Kuja, Budha, Guru, Shukra, Shani, mean Rahu, and Ketu.</li><li><code>S</code> be every chart sample used for an offered window.</li></ul><h2 id="exact-predicates-and-product-effects" tabindex="-1">Exact predicates and product effects <a class="header-anchor" href="#exact-predicates-and-product-effects" aria-label="Permalink to &quot;Exact predicates and product effects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule ID</th><th>Exact predicate at one sample</th><th>Effect</th></tr></thead><tbody><tr><td><code>vidyarambha.house-8-vacant</code></td><td><code>for every p in G: H(p) != 8</code></td><td><strong>Hard reject.</strong> Any known occupant of house 8 removes the candidate.</td></tr><tr><td><code>vidyarambha.budha-shukra-guru-9</code></td><td><code>H(Budha) = 9 AND H(Shukra) = 9 AND H(Guru) = 9</code></td><td><strong>Preference only.</strong> A pass supplies one tie-break; it changes neither raw score nor tier, and a miss has no penalty.</td></tr></tbody></table><p>The second formula is the project convention <code>vidyarambha-benefic-trio-co-location-v1</code>, registered under <code>election_chart.vidyarambha_co_location_policy_v1</code>. The inspected English text names the three grahas and the ninth house but does not explicitly distinguish all-three co-location from distributive or alternative readings. Version 1 therefore selects the strict, reproducible AND interpretation. It does not invent dignity, aspect, orb, house-lord, strength, or composite-score conditions.</p><h2 id="precedence-and-window-aggregation" tabindex="-1">Precedence and window aggregation <a class="header-anchor" href="#precedence-and-window-aggregation" aria-label="Permalink to &quot;Precedence and window aggregation&quot;">​</a></h2><p>The source does not state whether the favorable trio can neutralize the separately stated vacant-eighth condition. The owner-approved project convention <code>election_chart.vidyarambha_reject_precedence_policy_v1</code> resolves that product ambiguity as:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vacant-eighth hard reject &gt; all eligibility gates &gt; trio preference tie-break</span></span></code></pre></div><p>Therefore a failed vacancy rule always rejects, even when the trio passes. The trio never changes raw score or tier and never cancels a Panchangam, personal, safeguard, or chart rejection. This precedence is explicitly a project convention, not textual authority.</p><p>The window aggregator behaves exactly as follows:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Sample states</th><th>Window state and disposition</th></tr></thead><tbody><tr><td>Vacancy</td><td>Any <code>fail</code></td><td><code>fail</code>; reject</td></tr><tr><td>Vacancy</td><td>No fail, at least one <code>unknown</code></td><td><code>unknown</code>; retain for review</td></tr><tr><td>Vacancy</td><td>Every sample <code>pass</code></td><td><code>pass</code></td></tr><tr><td>Trio</td><td>Every sample <code>pass</code></td><td><code>pass</code>; one tie-break preference</td></tr><tr><td>Trio</td><td>Every sample definitively <code>fail</code></td><td><code>fail</code>; retain without preference or penalty</td></tr><tr><td>Trio</td><td>Mixed pass/fail, or unresolved samples</td><td><code>unknown</code> and unstable; retain for review</td></tr></tbody></table><p>When the local house frame is uncertain, both rules are unknown; the browser does not substitute the sidecar&#39;s house numbers. Missing, malformed, duplicated, noncanonical, or out-of-range nine-graha facts also fail closed. An unknown rule kind returns unknown and cannot fall through to another predicate.</p><h2 id="why-the-assessment-remains-partial" tabindex="-1">Why the assessment remains partial <a class="header-anchor" href="#why-the-assessment-remains-partial" aria-label="Permalink to &quot;Why the assessment remains partial&quot;">​</a></h2><p>Both event-specific Chapter VIII chart clauses are now computed. The product still labels the overall chart assessment <strong>partial/provisional</strong>, because the shared general election-chart baseline tracked by issue #284 is not yet a completed assessor. A valid result means the two disclosed Chapter VIII predicates were evaluated; it is not complete chart certification.</p><p>Non-Drik searches, unavailable chart service, malformed responses, boundary-uncertain frames, and bounded candidate searches add their own separate incompleteness. The child-age and ceremony-time disclosures remain information rather than chart predicates.</p><h2 id="full-rule-to-code-crosswalk" tabindex="-1">Full rule-to-code crosswalk <a class="header-anchor" href="#full-rule-to-code-crosswalk" aria-label="Permalink to &quot;Full rule-to-code crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source statement represented</th><th>Implementation</th><th>Treatment</th></tr></thead><tbody><tr><td>Most propitious marker: fifth day, fifth month, fifth year</td><td>First manual information row</td><td>Disclosed guidance, not a finder input.</td></tr><tr><td>Monday, Wednesday, Thursday, and Friday are good</td><td><code>allowed_varas</code></td><td>An unlisted weekday rejects the day.</td></tr><tr><td>Eight named Nakshatras are good</td><td><code>allowed_nakshatras</code></td><td>An unlisted active slot-time Nakshatra rejects the candidate.</td></tr><tr><td>Movable and common Rashis are good</td><td><code>allowed_lagnas</code></td><td>Four Chara and four Dvisvabhava Rashis form the slot-time allow-list.</td></tr><tr><td>Prefer forenoon and noon</td><td>Second manual information row</td><td>Preference disclosure; no invented hard cutoff.</td></tr><tr><td>Leave the eighth vacant</td><td><code>vidyarambha.house-8-vacant</code></td><td>Exact nine-graha vacancy predicate; hard rejection on failure.</td></tr><tr><td>Budha, Shukra, and Guru in the ninth</td><td><code>vidyarambha.budha-shukra-guru-9</code></td><td>Strict AND/co-location convention; tie-break only.</td></tr></tbody></table><h2 id="material-alternatives-kept-separate" tabindex="-1">Material alternatives kept separate <a class="header-anchor" href="#material-alternatives-kept-separate" aria-label="Permalink to &quot;Material alternatives kept separate&quot;">​</a></h2><h3 id="raman-chapter-xi-broader-education-elections" tabindex="-1">Raman Chapter XI: broader education elections <a class="header-anchor" href="#raman-chapter-xi-broader-education-elections" aria-label="Permalink to &quot;Raman Chapter XI: broader education elections&quot;">​</a></h3><p>Chapter XI, “Elections Pertaining to Education,” appears at <strong>internal printed pp. 46–47 (physical PDF pp. 50–51)</strong> in the inspected derivative. It discusses beginning study generally and then fields including Vedas, astrology, grammar, medicine, music, science, and trades. Its Nakshatra, Tithi, Lagna, Yoga, and chart guidance is a different scope. It is registered as <code>muhurta.vidyarambha.raman_chapter_xi_scope</code>, not blended into this Chapter VIII first-letter-writing assessor.</p><h3 id="muhurta-chintamani-5-37–5-38-distinct-lineage" tabindex="-1">Muhurta Chintamani 5.37–5.38: distinct lineage <a class="header-anchor" href="#muhurta-chintamani-5-37–5-38-distinct-lineage" aria-label="Permalink to &quot;Muhurta Chintamani 5.37–5.38: distinct lineage&quot;">​</a></h3><p>The 1945 fifth Nirnaya Sagar edition of Rama Daivajna&#39;s <em>Muhurta Chintamani</em>, with commentary catalogued under Narayanram Acharya, distinguishes Akshararambha in verse 5.37 from Vidyarambha in verse 5.38 and gives its own Tithi, Nakshatra, Vara, Lagna, and benefic-placement conditions:</p><ul><li><a href="https://jainqq.org/explore/002342/213" target="_blank" rel="noreferrer">verse 5.37, internal printed p. 197 / physical scan p. 213</a></li><li><a href="https://jainqq.org/explore/002342/214" target="_blank" rel="noreferrer">verse 5.38, internal printed p. 198 / physical scan p. 214</a></li></ul><p>Registered source ID: <code>MC-NSP-1945-5E</code>. These verses do not support the Raman Budha-Shukra-Guru trio. They are documented as <code>muhurta.vidyarambha.chintamani_divergence</code>, not used as corroboration and not merged into v1.</p><h2 id="deterministic-verification-corpus" tabindex="-1">Deterministic verification corpus <a class="header-anchor" href="#deterministic-verification-corpus" aria-label="Permalink to &quot;Deterministic verification corpus&quot;">​</a></h2><p>The shared Python/TypeScript oracle covers:</p><ul><li>full pass;</li><li>hard rejection;</li><li>preference miss retained without score or tier change;</li><li>simultaneous trio pass and vacancy failure, proving reject precedence;</li><li>missing, malformed, duplicated, and out-of-range facts;</li><li>mixed preference states;</li><li>every-sample preference failure;</li><li>house-frame uncertainty.</li></ul><p>The projection replay adds four dates across Hyderabad and Washington, D.C. It distinguishes external first-instant anchors from local DashaFlow contract projections and does not present the local projections as published-page matches.</p><p>Machine-readable evidence:</p><ul><li><code>tests/fixtures/election_chart_vidyarambha_oracle.json</code></li><li><code>tests/fixtures/election_chart_vidyarambha_projection.json</code></li></ul><h2 id="product-contract-and-limits" tabindex="-1">Product contract and limits <a class="header-anchor" href="#product-contract-and-limits" aria-label="Permalink to &quot;Product contract and limits&quot;">​</a></h2><p>Shared samskara exclusions, hard avoid windows, Amrit-Choghadiya and Tithi-family ranking preferences, personal scoring, raw weights, relative tiers, and the shared baseline are not established by the Chapter VIII citation. MCP exposes the stable <code>vidyarambha</code> identifier, the public label, the exact source scope, and the original manual disclosures. Python/MCP slot ranking does not call the remote chart sidecar.</p><p>For the shared sampling, boundary, data-minimization, and failure contract, see <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p>',43)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
